const listOutputItems = `-- name: ListOutputItems :many
SELECT
    output_items.id AS output_item_id,
    output_items.output_id,
    output_items.ordinal,
    output_items.role,
    output_items.label,
    asset_versions.id AS asset_version_id,
    asset_versions.asset_id,
    asset_versions.filename,
    asset_versions.content_type,
    asset_versions.size_bytes
FROM output_items
JOIN asset_versions
  ON asset_versions.id = output_items.asset_version_id
 AND asset_versions.company_id = output_items.company_id
JOIN assets
  ON assets.id = asset_versions.asset_id
 AND assets.company_id = asset_versions.company_id
WHERE output_items.company_id = $1::uuid
  AND output_items.output_id = ANY($2::uuid[])
ORDER BY output_items.output_id, output_items.ordinal
`

type ListOutputItemsParams struct {
	CompanyID uuid.UUID   `json:"company_id"`
	OutputIds []uuid.UUID `json:"output_ids"`
}

type ListOutputItemsRow struct {
	OutputItemID   uuid.UUID `json:"output_item_id"`
	OutputID       uuid.UUID `json:"output_id"`
	Ordinal        int32     `json:"ordinal"`
	Role           string    `json:"role"`
	Label          string    `json:"label"`
	AssetVersionID uuid.UUID `json:"asset_version_id"`
	AssetID        uuid.UUID `json:"asset_id"`
	Filename       string    `json:"filename"`
	ContentType    string    `json:"content_type"`
	SizeBytes      int64     `json:"size_bytes"`
}

func (q *Queries) ListOutputItems(ctx context.Context, arg ListOutputItemsParams) ([]ListOutputItemsRow, error) {
	rows, err := q.db.Query(ctx, listOutputItems, arg.CompanyID, arg.OutputIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListOutputItemsRow{}
	for rows.Next() {
		var i ListOutputItemsRow
		if err := rows.Scan(
			&i.OutputItemID,
			&i.OutputID,
			&i.Ordinal,
			&i.Role,
			&i.Label,
			&i.AssetVersionID,
			&i.AssetID,
			&i.Filename,
			&i.ContentType,
			&i.SizeBytes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

