const resolveOutputFileAttachment = `-- name: ResolveOutputFileAttachment :one
SELECT attachments.id
FROM outputs
JOIN companies ON companies.id=outputs.company_id AND companies.deleting_at IS NULL
JOIN company_members ON company_members.company_id=outputs.company_id AND company_members.user_id=$1::uuid AND company_members.status='active'
JOIN output_items
  ON output_items.output_id = outputs.id
 AND output_items.company_id = outputs.company_id
 AND output_items.ordinal = $2::integer
JOIN asset_versions
  ON asset_versions.id = output_items.asset_version_id
 AND asset_versions.company_id = output_items.company_id
 AND asset_versions.integrity_status = 'verified'
JOIN assets
  ON assets.id = asset_versions.asset_id
 AND assets.company_id = asset_versions.company_id
JOIN attachments
  ON attachments.id = asset_versions.attachment_id
 AND attachments.company_id = asset_versions.company_id
 AND attachments.status = 'ready'
WHERE outputs.id=$3::uuid
 AND outputs.company_id=$4::uuid
 AND outputs.run_id IS NOT DISTINCT FROM NULLIF($5::uuid,'00000000-0000-0000-0000-000000000000'::uuid)
  AND EXISTS (SELECT 1 FROM output_access AS access
      WHERE access.company_id = outputs.company_id
        AND access.output_id = outputs.id
        AND access.user_id = $1::uuid)
`

type ResolveOutputFileAttachmentParams struct {
	UserID    uuid.UUID `json:"user_id"`
	Ordinal   int32     `json:"ordinal"`
	OutputID  uuid.UUID `json:"output_id"`
	CompanyID uuid.UUID `json:"company_id"`
	RunID     uuid.UUID `json:"run_id"`
}

func (q *Queries) ResolveOutputFileAttachment(ctx context.Context, arg ResolveOutputFileAttachmentParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, resolveOutputFileAttachment,
		arg.UserID,
		arg.Ordinal,
		arg.OutputID,
		arg.CompanyID,
		arg.RunID,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

const retainOutputRunCompletion = `-- name: RetainOutputRunCompletion :exec
UPDATE outputs SET source_run_completed=true
FROM runs
WHERE outputs.company_id=runs.company_id AND outputs.run_id=runs.id
  AND runs.id=$1 AND runs.status='completed'
`

// The completion receipt commits with the terminal Run, before Task review.
func (q *Queries) RetainOutputRunCompletion(ctx context.Context, id uuid.UUID) error {
	_, err := q.db.Exec(ctx, retainOutputRunCompletion, id)
	return err
}
